interface.definition:
a!localVariables(
  local!reasonforreject,
  local!comment,
  {#"SYSTEM_SYSRULES_ButtonArrayLayout"(
    buttons: {
      #"SYSTEM_SYSRULES_buttonWidget_v1"(
        label: "Reject",
        style: "OUTLINE",
        color: "NEGATIVE",
        saveInto: {
          a!save(
            local!reasonforreject,
            true()
          )
        }
      )
    },
    align: "END"
  ),
  if(
    local!reasonforreject,
    {
     #"SYSTEM_SYSRULES_textField"(
       refreshAfter: "KEYPRESS",
       showCharacterCount: true(),
       showWhen: local!reasonforreject,
       value: local!comment,
       saveInto: a!save(
         local!comment,
         save!value
       )
     ),
     #"SYSTEM_SYSRULES_ButtonArrayLayout"(
       buttons: {
         #"SYSTEM_SYSRULES_buttonWidget_v1"(
           label: "cancel",
           icon: "pencil-ruler",
           style: "OUTLINE",
           color: "NEGATIVE",
           saveInto: a!save(local!reasonforreject,false())
         ),
         #"SYSTEM_SYSRULES_buttonWidget_v1"(
           label: "Accept",
           icon:"thumbs-o-up",
           style: "SOLID",
           color: "ACCENT",
           saveInto: {
             #"SYSTEM_SYSRULES_startProcess_v2"(
               processModel: #"_a-0000eff6-70cf-8000-9e5f-011c48011c48_1351758",
               processParameters: {

               }
             )
           }
         )
       }
     )
    },
    null()
  )
 }
)
